ALTER TABLE "pdv_pedido" ADD COLUMN "agendadoPara" TIMESTAMP(3), ADD COLUMN "iniciarPreparoEm" TIMESTAMP(3), ADD COLUMN "preparoIniciadoEm" TIMESTAMP(3), ADD COLUMN "antecedenciaMinutos" INTEGER;
ALTER TABLE "pdv_pedido" DROP CONSTRAINT "pdv_pedido_estado_valido";
ALTER TABLE "pdv_pedido" ADD CONSTRAINT "pdv_pedido_estado_valido" CHECK ("versao" >= 1 AND "numero" > 0 AND "status" IN ('AGENDADO','COZINHA','AGUARDANDO_COLETA','SAIU_ENTREGA','ENTREGUE','CANCELADO') AND ("status" <> 'ENTREGUE' OR "entregueEm" IS NOT NULL) AND ("status" <> 'CANCELADO' OR "canceladoEm" IS NOT NULL));
ALTER TABLE "pdv_pedido" ADD CONSTRAINT "pdv_pedido_agendamento_valido" CHECK (("agendadoPara" IS NULL AND "iniciarPreparoEm" IS NULL AND "antecedenciaMinutos" IS NULL AND "status" <> 'AGENDADO') OR ("agendadoPara" IS NOT NULL AND "iniciarPreparoEm" IS NOT NULL AND "antecedenciaMinutos" IS NOT NULL AND "antecedenciaMinutos" BETWEEN 1 AND 1440 AND "iniciarPreparoEm" = "agendadoPara" - "antecedenciaMinutos" * INTERVAL '1 minute' AND ("status" <> 'AGENDADO' OR "preparoIniciadoEm" IS NULL) AND ("status" IN ('AGENDADO','CANCELADO') OR "preparoIniciadoEm" IS NOT NULL)));
CREATE INDEX "pdv_pedido_agendamento_inicio_idx" ON "pdv_pedido" ("status","iniciarPreparoEm");
ALTER TABLE "pdv_pedido_evento" ADD COLUMN "chave" TEXT, ADD COLUMN "payloadHash" TEXT;
ALTER TABLE "pdv_pedido_evento" DROP CONSTRAINT "pdv_pedido_evento_valido";
ALTER TABLE "pdv_pedido_evento" ADD CONSTRAINT "pdv_pedido_evento_valido" CHECK ("versao" >= 1 AND ("de" IS NULL OR "de" IN ('AGENDADO','COZINHA','AGUARDANDO_COLETA','SAIU_ENTREGA','ENTREGUE','CANCELADO')) AND (("chave" IS NULL AND "payloadHash" IS NULL) OR ("chave" IS NOT NULL AND "payloadHash" IS NOT NULL AND "usuarioId" IS NOT NULL)) AND "para" IN ('AGENDADO','COZINHA','AGUARDANDO_COLETA','SAIU_ENTREGA','ENTREGUE','CANCELADO'));
CREATE UNIQUE INDEX "pdv_pedido_evento_organizacaoId_unidadeId_chave_key" ON "pdv_pedido_evento" ("organizacaoId","unidadeId","chave");
